import * as THREE from './vendor/three.module.js';
import {makeBike} from './bike-model.js';
export function installSoftwareBikeView(){
 const canvas=document.createElement('canvas');canvas.id='bike3d';canvas.setAttribute('aria-hidden','true');document.querySelector('#world').after(canvas);const ctx=canvas.getContext('2d');const bike=makeBike(),camera=new THREE.PerspectiveCamera(37,1,.1,80);let width=0,height=0,lastDraw=0,orbit=0,drag=false,lastX=0;
 const host=document.querySelector('#game');host.addEventListener('pointerdown',e=>{if(!document.body.classList.contains('racing')&&e.target.tagName==='CANVAS'){drag=true;lastX=e.clientX;host.setPointerCapture(e.pointerId)}});host.addEventListener('pointermove',e=>{if(drag){orbit+=(e.clientX-lastX)*.007;lastX=e.clientX}});host.addEventListener('pointerup',()=>drag=false);host.addEventListener('pointercancel',()=>drag=false);
 const light=new THREE.Vector3(-.4,.8,-.45).normalize(),viewLight=new THREE.Vector3(),normalMatrix=new THREE.Matrix3(),modelView=new THREE.Matrix4(),projection=new THREE.Matrix4();
 window.bikeView={render(o){
  if(o.clock-lastDraw<1/24&&width===o.w&&height===o.h)return;lastDraw=o.clock;if(width!==o.w||height!==o.h){width=o.w;height=o.h;canvas.width=width;canvas.height=height}ctx.clearRect(0,0,width,height);if(!o.menu&&o.camera==='cockpit')return;
  bike.rider.visible=!o.menu;bike.accent.color.set(o.color);bike.accent.emissive.set(o.color);bike.silver.color.set(o.selected===0?'#c5cdd3':o.selected===1?'#cbdfe5':'#647082');
  if(o.menu){camera.fov=37;camera.aspect=width/height;camera.position.set(5.1,2.9,-6);camera.lookAt(0,1,0);camera.updateProjectionMatrix();camera.projectionMatrix.elements[8]=width>760?-.40:-.3;camera.projectionMatrix.elements[9]=width>760?0:-.23;bike.group.position.set(0,0,0);bike.group.rotation.set(0,orbit+Math.sin(o.clock*.13)*.13,0);bike.group.scale.setScalar(width>760?.82:Math.min(.64,width/650));bike.wheels.forEach(w=>w.rotation.x=0)}else{camera.fov=THREE.MathUtils.radToDeg(2*Math.atan(height/(2*o.focal)));camera.aspect=width/height;camera.position.set(o.camX,o.camY,0);camera.lookAt(o.camX,o.camY,-1);camera.updateProjectionMatrix();camera.projectionMatrix.elements[9]=2*o.horizon/height-1;bike.group.position.set(o.x,0,-12.5);bike.group.rotation.set(0,-o.steer*.10,-o.steer*.21);bike.group.scale.setScalar(1.05);bike.wheels.forEach(w=>w.rotation.x=-o.distance/.7)}
  camera.updateMatrixWorld();camera.projectionMatrixInverse.copy(camera.projectionMatrix).invert();bike.group.updateMatrixWorld(true);viewLight.copy(light).transformDirection(camera.matrixWorldInverse);bike.glows.forEach(g=>{g.visible=o.boosting&&!o.menu});
  const ground=new THREE.Vector3(o.menu?0:o.x,0,o.menu?0:-12.5).project(camera);const gx=(ground.x+1)*width/2,gy=(1-ground.y)*height/2;ctx.fillStyle='#00000070';ctx.beginPath();ctx.ellipse(gx,gy,width*(o.menu?.175:.055),height*.025,0,0,Math.PI*2);ctx.fill();
  const faces=[];bike.group.traverseVisible(mesh=>{if(!mesh.isMesh)return;const geo=mesh.geometry,p=geo.attributes.position.array,n=geo.attributes.normal.array,index=geo.index?.array;if(!index)return;modelView.multiplyMatrices(camera.matrixWorldInverse,mesh.matrixWorld);normalMatrix.getNormalMatrix(modelView);projection.multiplyMatrices(camera.projectionMatrix,modelView);const m=projection.elements,nm=normalMatrix.elements,mv=modelView.elements;const vertices=new Float32Array(p.length/3*6);
   for(let j=0;j<p.length;j+=3){const x=p[j],y=p[j+1],z=p[j+2],den=m[3]*x+m[7]*y+m[11]*z+m[15],k=j*2;vertices[k]=((m[0]*x+m[4]*y+m[8]*z+m[12])/den+1)*width/2;vertices[k+1]=(1-(m[1]*x+m[5]*y+m[9]*z+m[13])/den)*height/2;vertices[k+2]=mv[2]*x+mv[6]*y+mv[10]*z+mv[14];let nx=nm[0]*n[j]+nm[3]*n[j+1]+nm[6]*n[j+2],ny=nm[1]*n[j]+nm[4]*n[j+1]+nm[7]*n[j+2],nz=nm[2]*n[j]+nm[5]*n[j+1]+nm[8]*n[j+2];const len=Math.hypot(nx,ny,nz);vertices[k+3]=nx/len;vertices[k+4]=ny/len;vertices[k+5]=nz/len}
   const material=mesh.material,color=material.color.clone().convertLinearToSRGB(),emissive=material.emissive?.getHex()>0;const base=[color.r*255,color.g*255,color.b*255];
   for(let i=0;i<index.length;i+=3){const a=index[i]*6,b=index[i+1]*6,c=index[i+2]*6;if(vertices[a+2]>-.1||vertices[b+2]>-.1||vertices[c+2]>-.1)continue;const winding=(vertices[b]-vertices[a])*(vertices[c+1]-vertices[a+1])-(vertices[b+1]-vertices[a+1])*(vertices[c]-vertices[a]);if(winding>=0&&material.side!==THREE.DoubleSide)continue;let nx=(vertices[a+3]+vertices[b+3]+vertices[c+3])/3,ny=(vertices[a+4]+vertices[b+4]+vertices[c+4])/3,nz=(vertices[a+5]+vertices[b+5]+vertices[c+5])/3;const len=Math.hypot(nx,ny,nz);nx/=len;ny/=len;nz/=len;let diffuse=Math.max(0,nx*viewLight.x+ny*viewLight.y+nz*viewLight.z);const spec=Math.pow(Math.max(0,nz*.93+ny*.30-nx*.18),material.metalness>.5?28:9)*(material.metalness>.5?100:8);const rim=Math.pow(1-Math.abs(nz),3)*45;const intensity=emissive?1.12:.24+.76*diffuse+.13*Math.max(0,ny);const rgb=base.map((v,k)=>Math.min(255,Math.round(v*intensity+spec+rim*(k===0?.55:k===1?.8:1))));faces.push({xy:[vertices[a],vertices[a+1],vertices[b],vertices[b+1],vertices[c],vertices[c+1]],z:(vertices[a+2]+vertices[b+2]+vertices[c+2])/3,color:'rgb('+rgb.join(',')+')'})}
  });faces.sort((a,b)=>a.z-b.z);ctx.lineWidth=.45;for(const f of faces){ctx.beginPath();ctx.moveTo(f.xy[0],f.xy[1]);ctx.lineTo(f.xy[2],f.xy[3]);ctx.lineTo(f.xy[4],f.xy[5]);ctx.closePath();ctx.fillStyle=f.color;ctx.strokeStyle=f.color;ctx.fill();ctx.stroke()}
 },stats(){return{mode:'software-3d'}}};document.querySelector('#modelHint').textContent='DRAG TO INSPECT YOUR MACHINE';
}
